import{_ as l,r as t,o as p,c as r,e,a as s,s as a}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Introduction - October CMS - 4.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Settings Page Registration","slug":"settings-page-registration","link":"#settings-page-registration","children":[{"level":3,"title":"Settings Properties","slug":"settings-properties","link":"#settings-properties","children":[]}]},{"level":2,"title":"Linking to a Model Class","slug":"linking-to-a-model-class","link":"#linking-to-a-model-class","children":[]},{"level":2,"title":"Linking to a Controller Class","slug":"linking-to-a-controller-class","link":"#linking-to-a-controller-class","children":[{"level":3,"title":"Settings Page Class Definition","slug":"settings-page-class-definition","link":"#settings-page-class-definition","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/extend/settings/settings.md","filePath":"4.x/extend/settings/settings.md"}'),c={name:"4.x/extend/settings/settings.md"};function g(d,n,u,k,h,m){const o=t("pre-heading"),i=t("post-heading");return p(),r("div",null,[e(o),n[0]||(n[0]=s("h1",null,"Introduction",-1)),e(i),n[1]||(n[1]=a(`<p>There are two main ways that plugins can configure the system. It is a good idea to first decide which is the best option for your requirements.</p><ul><li><a href="./file-settings.html">file-based configuration</a> with no user-interface, stored in the file system.</li><li><a href="./model-settings.html">model-based settings</a> with an optional user-interface, stored in the database.</li></ul><p>Using model-based settings with backend pages provide a better user experience, but they carry more overhead for the initial development. File-based configuration is suitable for configuration that is rarely modified and has no interface, such as policy configuration.</p><h2 id="settings-page-registration"><a href="#settings-page-registration" class="header-anchor">#</a> Settings Page Registration</h2><p>When using model-based settings, you may optionally register them with the dedicated area for managing settings and configuration, accessed by clicking the <strong>Settings</strong> link in the main menu.</p><p>Settings pages must be registered by overriding the <code>registerSettings</code> method inside the <a href="./../extending.html">plugin registration file</a>. The method returns an array with a key for each settings item and the value configures the settings model or controller to appear in the settings area. The following is an example of registering a settings model.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;settings&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User Settings&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage user based settings.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;CATEGORY_USERS&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-cog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="settings-properties"><a href="#settings-properties" class="header-anchor">#</a> Settings Properties</h3><p>The following properties are available for each key when registering settings.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>specifies the menu label localization string key, required.</td></tr><tr><td><strong>category</strong></td><td>specifies a category label localization string key, for grouping settings pages together, required.</td></tr><tr><td><strong>keywords</strong></td><td>specifies keywords used for searching settings.</td></tr><tr><td><strong>order</strong></td><td>a numerical weight when determining the display order.</td></tr><tr><td><strong>icon</strong></td><td>an icon name from the <a href="./../../element/available-icons.html">October CMS icon collection</a>, optional.</td></tr><tr><td><strong>iconSvg</strong></td><td>an SVG icon to be used in place of the standard icon, the SVG icon should be a rectangle and can support colors, optional.</td></tr><tr><td><strong>url</strong></td><td>the backend URL the menu item should refer to, eg. <code>Backend::url(&#39;author/plugin/controller/action&#39;)</code>.</td></tr><tr><td><strong>class</strong></td><td>the model class the settings item should refer to, eg. <code>Acme\\User\\Models\\UserSetting::class</code>.</td></tr><tr><td><strong>permissions</strong></td><td>an array of permissions the backend user must have in order to view the menu item (Note: direct access of URLs still requires separate permission checks), optional.</td></tr><tr><td><strong>context</strong></td><td>specifies the placement of the settings item, either <code>system</code> or <code>mysettings</code>. Default: <code>system</code>.</td></tr><tr><td><strong>size</strong></td><td>the settings form size when used with a <code>class</code> definition. Supported values: <code>tiny</code>, <code>small</code>, <code>medium</code>, <code>large</code>, <code>huge</code>, <code>giant</code>, <code>adaptive</code>. Default: <code>large</code>.</td></tr></tbody></table></div><p>For interoperability with other plugins, the following general constants are available for the <code>category</code> property.</p>`,11)),n[2]||(n[2]=s("div",{class:"content-list",markdown:"1"},[s("ul",null,[s("li",null,"CATEGORY_CMS"),s("li",null,"CATEGORY_MISC"),s("li",null,"CATEGORY_MAIL"),s("li",null,"CATEGORY_LOGS"),s("li",null,"CATEGORY_SHOP"),s("li",null,"CATEGORY_TEAM"),s("li",null,"CATEGORY_USERS"),s("li",null,"CATEGORY_SOCIAL"),s("li",null,"CATEGORY_SYSTEM"),s("li",null,"CATEGORY_EVENTS"),s("li",null,"CATEGORY_BACKEND"),s("li",null,"CATEGORY_CUSTOMERS"),s("li",null,"CATEGORY_MYSETTINGS"),s("li",null,"CATEGORY_NOTIFICATIONS"),s("li",null,"CATEGORY_GLOBALS"),s("li",null,"CATEGORY_COLLECTIONS")])],-1)),n[3]||(n[3]=a(`<p>The optional <code>keywords</code> parameter is used by the settings search feature. If keywords are not provided, the search uses only the settings item label and description.</p><h2 id="linking-to-a-model-class"><a href="#linking-to-a-model-class" class="header-anchor">#</a> Linking to a Model Class</h2><p>When linking to a model <code>class</code> specified in the settings properties, you do not need to build your own controller, and this is useful for the majority of cases. The following example creates a link to a settings model, described more in the <a href="./model-settings.html">model settings article</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;settings&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;User Settings&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage user based settings.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-cog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>User<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>UserSetting</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;security location&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;permissions&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.users.access_settings&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>A generic backend controller is used for the form, with basic features like saving and resetting the values to default. Active navigation is configured automatically. Permissions defined are also enforced by the controller.</p><h2 id="linking-to-a-controller-class"><a href="#linking-to-a-controller-class" class="header-anchor">#</a> Linking to a Controller Class</h2><p>When specifying a page <code>url</code> in the settings properties, you have the option to build your own controller and link it in the settings area. The next example shows how to create a link to a backend page.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSettings</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;location&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Locations&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage available user countries and states.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;category&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Users&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-globe&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;url&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/user/locations&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">500</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;keywords&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;geography place placement&#39;</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="settings-page-class-definition"><a href="#settings-page-class-definition" class="header-anchor">#</a> Settings Page Class Definition</h3><p>Settings page controllers can be any <a href="./../system/controllers.html">backend controller</a>, except to make things easier, you may extend the <code>Backend\\Classes\\SettingsController</code> base class. This class registers the setting navigation context in the controller automatically. All you need to do is provide the settings code in the <code>$settingsItemCode</code> property, used to determine the active menu item.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>SettingsController</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$settingsItemCode</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;location&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">index</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../system/controllers.html">Backend Controllers</a></li></ul></div>`,13))])}const b=l(c,[["render",g]]);export{y as __pageData,b as default};
